css:
/* GENERAL PRINT FORMAT */
body, html {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
    font-size: 14px;
    color: #111;
}

.print-format {
    width: 8.27in;
    margin: auto;
    background: #fff;
    padding: 20px 40px;
    box-sizing: border-box;
}

/* PAGE */
.page {
    width: 100%;
    margin-bottom: 40px;
    box-sizing: border-box;
}

/* TITLE */
.title-row {
    text-align: center;
    margin-bottom: 20px;
}

.title {
    font-size: 16px;
    font-weight: bold;
    margin-bottom: 5px;
}

/* SECTION */
.section-title {
    font-weight: bold;
    margin: 25px 0 10px 0;
}

/* FIELD ROWS - TWO COLUMNS */
.field-row {
    display: flex;
    justify-content: space-between;
    margin: 10px 0;
}

.field-row .label {
    font-weight: bold;
    width: 45%; /* left column width */
    text-align: left;
}

.field-row .value {
    width: 50%; /* right column width */
    text-align: left;
    border-bottom: 1px solid #ccc;
    padding: 4px 6px;
    box-sizing: border-box;
}

/* DECLARATION */
.declaration {
    margin-top: 15px;
    text-align: justify;
}

/* SIGNATURE */
.signature-space {
    height: 80px;
    margin-top: 10px;
    border-bottom: 1px solid #ccc;
}

/* BOTTOM FIELDS */
.bottom-fields {
    margin-top: 20px;
}

.bottom-row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 10px;
}

.bottom-label {
    font-weight: bold;
    width: 45%;
    text-align: left;
}

.bottom-line {
    width: 50%;
    text-align: left;
    border-bottom: 1px solid #ccc;
    padding: 4px 6px;
    box-sizing: border-box;
}

/* IMAGE */
.page img {
    max-width: 200px;
    display: block;
    margin: 0 auto 20px auto;
}

/* OPTIONAL SECTION GAP */
.section-gap {
    margin-top: 20px;
}
